const iso=d=>d.toISOString().slice(0,10),parseDate=v=>new Date(v+'T00:00:00Z');
const shiftDate=(v,n)=>{const d=parseDate(v);d.setUTCDate(d.getUTCDate()+n);return iso(d)};
const validDate=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(parseDate(v).getTime())&&iso(parseDate(v))===v;
const todayDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const weekStart=date=>shiftDate(date,-((parseDate(date).getUTCDay()+6)%7));
function weekRange(first,last=first,today=todayDate()){const start=weekStart(first),sunday=shiftDate(weekStart(last),6),yesterday=shiftDate(today,-1);return {start,end:sunday<today?sunday:yesterday}}
const periodWeeks=()=>Math.round((parseDate(weekStart(state.endDate||state.date))-parseDate(weekStart(state.date)))/604800000)+1;
function dateRange(){const d=parseDate(state.date),last=validDate(state.endDate)&&state.endDate>=state.date?state.endDate:state.date;if(state.day==='week')return weekRange(state.date,last);if(state.day==='month'){const e=parseDate(last);return {start:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),1))),end:iso(new Date(Date.UTC(e.getUTCFullYear(),e.getUTCMonth()+1,0)))}}return {start:state.date,end:last}}
const days=()=>Math.round((parseDate(dateRange().end)-parseDate(dateRange().start))/86400000)+1;
const periodMonths=()=>{const r=dateRange(),s=parseDate(r.start),e=parseDate(r.end);return (e.getUTCFullYear()-s.getUTCFullYear())*12+e.getUTCMonth()-s.getUTCMonth()+1};
function monthUnits(){const r=dateRange(),d=parseDate(state.date);if(state.day==='week')return days()/new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();let total=0,start=r.start;while(start<=r.end){const t=parseDate(start),end=iso(new Date(Date.UTC(t.getUTCFullYear(),t.getUTCMonth()+1,0))),stop=end<r.end?end:r.end;total+=(Math.round((parseDate(stop)-parseDate(start))/86400000)+1)/Number(end.slice(8));start=shiftDate(end,1)}return total}
function compareRange(kind=state.comparison){const r=dateRange(),d=parseDate(r.start);if(state.day==='month'){const count=periodMonths(),offset=kind==='yoy'?12:count;return {start:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()-offset,1))),end:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()-offset+count,0)))}}if(kind==='yoy'){const back=v=>{const t=parseDate(v),year=t.getUTCFullYear()-1,month=t.getUTCMonth(),day=Math.min(t.getUTCDate(),new Date(Date.UTC(year,month+1,0)).getUTCDate());return iso(new Date(Date.UTC(year,month,day)))};return {start:back(r.start),end:back(r.end)}}const offset=state.day==='week'?periodWeeks()*7:days();return {start:shiftDate(r.start,-offset),end:shiftDate(r.end,-offset)}}
const rangeText=r=>r.start+' ～ '+r.end;
const money=n=>Math.round(n).toLocaleString('zh-CN');
