const route=()=>location.hash.slice(1)||'home';
function persist(){history.replaceState({filters:{...state},scroll:window.scrollY,depth:history.state?.depth||0},'')}
function go(id){persist();state.point=null;history.pushState({filters:{...state},scroll:0,depth:(history.state?.depth||0)+1},'','#'+id);render();window.scrollTo(0,0)}
function comparison(m,type='mom'){const delta=current(m)-previous(m,type),v=m.kind==='rate'?delta:previous(m,type)===0?0:delta/Math.abs(previous(m,type))*100;const bad=m.lower?v>0:v<0;return `<span class="${bad?'red':'green'}">${m.unit==='家'?(delta>0?'+':'')+money(delta):signed(v)}${m.unit==='家'?'家':m.kind==='rate'?'pp':'%'}</span>`}
function changes(m){return `<div class="metric-changes"><span>环比 ${comparison(m)}</span><span>${m.sameStore?'同店同比':'同比'} ${comparison(m,'yoy')}</span></div>`}
function metricCard(id,small=false){const m=metrics[id],v=current(m);return `<button class="group-metric ${small?'small':''}" data-go="${id}"><div class="metric-label">${m.name}<span>›</span></div><div class="metric-number ${m.color||''}">${fmt(v,m)}<small>${unit(m)}</small></div>${m.target!==undefined?`<div class="metric-hint">目标 ${m.lower?'≤':'≥'}${m.target}${m.unit}</div>`:''}${changes(m)}</button>`}
function overviewGroup(name,icon,ids,note=''){return `<section class="overview-block overview-compact" aria-label="${name}指标"><div class="overview-columns"><h2>${icon}${name}</h2><span>本期</span><span>环比</span><span>同比</span><span></span></div>${ids.map(id=>{const m=metrics[id],v=current(m);return `<button class="overview-row" ${id==='fulltime'?'data-scroll="fulltime-trend"':`data-go="${id}"`} aria-label="${m.name} ${fmt(v,m)}${unit(m)}，环比 ${comparison(m).replace(/<[^>]+>/g,'')}，同比 ${comparison(m,'yoy').replace(/<[^>]+>/g,'')}，查看分析"><span class="overview-name">${m.name}<small>${unit(m)}</small></span><b class="overview-value" style="--digits:${fmt(v,m).length}">${fmt(v,m)}</b><span class="overview-delta">${comparison(m)}</span><span class="overview-delta">${comparison(m,'yoy')}</span><span class="overview-arrow" aria-hidden="true">›</span></button>`}).join('')}${note?`<p class="overview-note">${note}</p>`:''}</section>`}
function section(name,extra=''){return `<div class="section-title"><span>${name}</span><small>${extra}</small></div>`}
function dateTabs(){return `<div class="date-tabs" role="group" aria-label="日期类型">${[['day','日'],['week','周'],['month','月']].map(([id,n])=>`<button data-date-type="${id}" aria-pressed="${state.day===id}" class="${state.day===id?'selected':''}">${n}</button>`).join('')}</div>`}
function dateLabel(date,type=state.day){const d=parseDate(date),short=v=>`${Number(v.slice(5,7))}月${Number(v.slice(8))}日`;if(type==='month')return `${d.getUTCFullYear()}年${d.getUTCMonth()+1}月`;if(type==='week'){const {start,end}=weekRange(date),thursday=parseDate(shiftDate(start,3)),week=Math.ceil(((thursday- new Date(Date.UTC(thursday.getUTCFullYear(),0,1)))/86400000+1)/7),range=v=>`${start.slice(0,4)!==end.slice(0,4)?v.slice(0,4)+'/':''}${Number(v.slice(5,7))}/${Number(v.slice(8))}`;return `第${week}周 (${range(start)}–${range(end)})`}return `${short(date)} 周${'日一二三四五六'[d.getUTCDay()]}`}
function dateOptions(){const anchor=state.day==='week'?shiftDate(todayDate(),-1):state.date>'2026-09-18'?state.date:'2026-09-18',d=parseDate(anchor);const options=Array.from({length:state.day==='day'?31:12},(_,i)=>state.day==='month'?iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()-i,1))):state.day==='week'?shiftDate(anchor,-((d.getUTCDay()+6)%7)-i*7):shiftDate(anchor,-i));const selected=dateRange().start;return options.includes(selected)?options:[selected,...options]}
function datePicker(compact=false){const r=dateRange(),multiple=!!state.endDate&&(state.day==='week'?periodWeeks()>1:state.endDate!==state.date),label=multiple?(state.day==='month'?`${dateLabel(r.start)} – ${r.start.slice(0,4)===r.end.slice(0,4)?Number(r.end.slice(5,7))+'月':dateLabel(r.end)}`:`${r.start.replaceAll('-','/')} – ${r.end.replaceAll('-','/')}`):dateLabel(state.date);const sameYearMonths=compact&&multiple&&state.day==='month'&&r.start.slice(0,4)===r.end.slice(0,4);const displayLabel=sameYearMonths?`${r.start.slice(0,4)}年${Number(r.start.slice(5,7))}–${Number(r.end.slice(5,7))}月`:compact&&multiple?label.split(' – ').map((text,i)=>`<span class="date-line">${i?'– ':''}${text}</span>`).join(''):compact&&state.day==='week'?label.replace(' (','<span class="date-line">(')+'</span>':label;return `<details class="date-control" id="date-control"><summary class="date-trigger" id="date-open" aria-label="选择统计日期" title="${rangeText(r)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v5m10-5v5M3 11h18"/></svg><span class="date-copy">${displayLabel}</span><svg class="date-caret" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg></summary><div class="date-popover">${dateTabs()}<div class="date-options ${state.day}" role="group" aria-label="选择日期">${dateOptions().map(date=>{const selected=!multiple&&(state.day==='day'?date===state.date:state.day==='month'?date.slice(0,7)===r.start.slice(0,7):date===r.start);return `<button data-date-value="${date}" aria-pressed="${selected}" class="${selected?'selected':''}">${dateLabel(date)}</button>`}).join('')}</div><button class="date-other" id="date-other">${state.day==='month'?'选择月份期间…':state.day==='day'?'选择日期区间…':'选择周期间…'}</button></div></details>`}
function filter(){return `<div class="hero date-only">${datePicker()}</div>`}
function homeHeader(title){return `<section class="dashboard-hero" aria-label="集团概况"><div class="group-identity"><span class="group-mark" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="10" y="4" width="13" height="24" rx="2"/><path d="M10 15H6a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h4m13-15h3a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2h-3M14 9h5m-5 5h5m-5 5h5m-5 5h5"/></svg></span><div class="group-name"><h1>${title}</h1><p>DEMO餐饮集团</p></div></div><div class="hero-periods">${datePicker(true)}</div></section>`}
function footer(){const v=((document.querySelector('script[src*="app.js"]')||{}).src||'').match(/v=([\w.-]+)/);return '<footer class="footer">全部为模拟数据 · 点击指标可查看分析<br>金额与人数均为演示口径，不代表真实集团经营'+(v?'<br><span class="build-tag">build '+v[1]+'</span>':'')+'</footer>'}
