function targetGap(id,targetId){const value=current(metrics[id]),target=current(metrics[targetId]);return (value/target-1)*100}
function coreRow(id,name,targetId,rateId,rateName){const m=metrics[id],rate=metrics[rateId],gap=targetGap(id,targetId),rateTarget=rateId==='receiptDiscountRate'?rate.target:current(metrics[targetId])/current(metrics.target)*100,rateGap=current(rate)-rateTarget;return `<div class="core-item"><button class="core-main" data-go="${id}" aria-label="${name}，查看分析"><span class="core-name">${name} <b class="${id==='receipt'?'':'orange'}">¥${fmt(current(m),m)}${unit(m).replace('元','')}</b></span><span class="core-target ${gap<0?'orange':''}">${signed(gap)}%</span>${comparison(m)}${comparison(m,'yoy')}<span class="core-arrow" aria-hidden="true">›</span></button><button class="core-secondary" data-go="${rateId}" aria-label="${rateName}，查看分析"><span>${rateName} <span class="core-rate">${fmt(current(rate),rate)}%</span></span><span>${signed(rateGap)}pp</span>${comparison(rate)}${comparison(rate,'yoy')}<span></span></button></div>`}
function groupOverview(){return `<section class="group-overview card" aria-label="集团概览"><div class="scale-grid">${[['stores','在营门店','门店'],['members','累计会员','会员'],['fulltime','员工数（正式工）','员工']].map(([id,name,icon])=>{const m=metrics[id];return `<button class="scale-metric" data-go="${id}"><div class="scale-number">${overviewIcons[icon]}<b>${fmt(current(m),m)}<small>${unit(m)}</small></b></div><div class="scale-name">${name}</div>${changes(m)}</button>`}).join('')}</div><div class="core-panel"><div class="core-columns"><span>核心指标</span><span>目标对比</span><span>环比</span><span>同比</span><span></span></div>${coreRow('receipt','门店实收','target','receiptDiscountRate','折扣率')}${coreRow('profit','门店利润','profitTarget','profitShare','利润率')}${coreRow('groupProfit','集团利润','groupProfitTarget','groupProfitShare','集团利润率')}</div><p class="core-note">利润为预算测算；门店实收及门店利润同比按同店口径。点击指标查看明细。</p></section>`}
function overviewDetails(id){if(id==='stores')return overviewGroup('门店指标',overviewIcons['门店'],['building','area'],state.endDate?'期间坪效 · 按所选期间折算':(state.day==='day'?'日':state.day==='week'?'周':'月')+'坪效 · 按天数折算');if(id==='fulltime')return overviewGroup('员工指标',overviewIcons['员工'],['fulltime','hourly','efficiency'],'正式工：'+metrics.fulltime.formula);if(id==='members')return overviewGroup('会员指标',overviewIcons['会员'],['active','activeRate'],'活跃会员：最近3个月消费次数大于等于1的会员');return ''}
function home(){return `${section('集团概览')}${groupOverview()}${section('集团体检','四大核心能力')}<div class="health-grid">${['cash','sameStore','profitGrowth','opening'].map(id=>{const m=metrics[id];return `<button class="health-card" data-go="${id}"><div class="health-title"><i>${{cash:'▣',sameStore:'⌁',profitGrowth:'◴',opening:'↗'}[id]}</i><b>${m.name}</b><span>${m.caption}</span><em>›</em></div><div class="health-number ${current(m)<m.target?'orange':''}">${m.id==='profitGrowth'&&current(m)>0?'+':''}${fmt(current(m),m)}<small>${unit(m)}</small></div><div class="metric-hint">目标 ${m.lower?'≤':'≥'}${m.target}${m.unit}</div>${changes(m)}</button>`}).join('')}</div>${section('巡店建议','利润 × 巡店得分')}<div class="quadrant-grid">${quadrants.slice(0,4).map(([id,name,n,desc,color])=>`<button class="quadrant" data-go="${id}"><div class="quadrant-title ${color}"><i aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${quadrantIcons[id]}</svg></i><b>${name}</b><span aria-hidden="true">›</span></div><strong class="quadrant-number ${color}">${n}<small>家</small></strong><p>${desc}</p>${changes(metrics[id])}</button>`).join('')}</div><button class="pending-class" data-go="unrated">另有 197 家待评估，四类已评估合计 202 家<span>›</span></button>${footer()}`}
const visits=[{market:'华南市场',store:'海滨示范店',priority:'优先巡查',color:'red',issue:'利润率 −2.3%，巡店得分 68 分',action:'重点核查食材耗用、损耗与当班操作。',owner:'区域督导 · 建议24小时内',metric:'problem'}, {market:'华东市场',store:'中心示范店',priority:'重点关注',color:'orange',issue:'利润率 15.2%，巡店得分 72 分',action:'核查卫生、服务及标准执行，预防利润下滑。',owner:'运营负责人 · 建议3日内',metric:'hidden'}, {market:'华中市场',store:'大学城示范店',priority:'经营辅导',color:'blue',issue:'利润率 5.1%，巡店得分 91 分',action:'复核商圈客流、商品结构和排班效率。',owner:'市场负责人 · 建议本周',metric:'potential'}];
function isFullMonth(){const r=dateRange(),d=parseDate(r.start);return r.start.endsWith('-01')&&r.end===iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)))}
const isMonthlyPnl=()=>state.day==='month'||isFullMonth();
function pnlRow(id){const m=metrics[id];if(isMonthlyPnl()){const budgetId=id==='receipt'?'target':id==='food'?null:id,actualId=['receipt','food'].includes(id)?id:id+'Actual';return `<div class="pnl-month-row ${id==='profit'?'profit-total':''}"><button class="pnl-month-name" ${id==='profit'?'data-scroll="profit-trend"':`data-go="${id}"`}>${id==='receipt'?'实收':m.name.replace('预算','')} <span aria-hidden="true">›</span></button>${[budgetId,actualId].map((metricId,i)=>{if(!metricId)return '<div class="pnl-month-empty" aria-label="暂无预算值">—</div>';const v=metrics[metricId];return `<button class="pnl-month-cell ${i?'actual':''}" ${metricId==='profit'?'data-scroll="profit-trend"':`data-go="${metricId}"`} aria-label="${v.name}，查看分析"><b>¥ ${money(current(v))}</b><small>占实收 ${(current(v)/current(metrics.receipt)*100).toFixed(1)}%</small>${changes(v)}</button>`}).join('')}</div>`}return `<button class="pnl-row ${id==='profit'?'profit-total':''}" ${id==='profit'?'data-scroll="profit-trend"':`data-go="${id}"`}><div class="row"><span>${id==='receipt'?'实收':m.name} ›</span><b>¥ ${money(current(m))}</b></div><div class="pnl-meta"><span>占实收 <b>${(current(m)/current(metrics.receipt)*100).toFixed(1)}%</b></span>${changes(m)}</div></button>`}
function profitBreakdown(){return `${section('门店损益明细')}<div class="card pnl">${isMonthlyPnl()?'<div class="pnl-month-head"><span>指标</span><span>预算</span><span>实际</span></div>':''}${['receipt',...costs.map(x=>x[0]),'profit'].map(pnlRow).join('')}${isMonthlyPnl()?'<div class="pnl-actual-note">实际费用及利润为演示值；实收预算采用目标实收，食材成本未提供预算值。</div>':''}</div>`}
