function channelDetail(channel){return `${filter()}${receiptChannel(channel)}<button class="back-home" data-go="receipt">返回实收达成率 ›</button>${footer()}`}
const channelRevenue=channel=>flow(channel==='dining'?2982000:1988000);
function allocateAmount(total,weights){const sum=weights.reduce((a,b)=>a+b,0);let used=0;return weights.map((w,i)=>{const n=i===weights.length-1?Math.round(total*100)-used:Math.round(total*100*w/sum);used+=n;return n/100})}
function receiptMarketRows(channel='total'){
 const receipts=allocateAmount(current(metrics.receipt),receiptMarkets.map(x=>x[1]));
 const targets=allocateAmount(current(metrics.target),receiptMarkets.map(x=>x[1]/x[2]));
 const dining=allocateAmount(channelRevenue('dining'),receiptMarkets.map((x,i)=>receipts[i]*x[3]));
 return receiptMarkets.map((x,i)=>{const actual=channel==='dining'?dining[i]:channel==='delivery'?receipts[i]-dining[i]:receipts[i],target=channel==='dining'?targets[i]*.6:channel==='delivery'?targets[i]*.4:targets[i];return {mi:i,name:x[0],actual,target,rate:actual/target*100}}).sort((a,b)=>b.rate-a.rate)
}
const receiptAmount=n=>n>=100000000?(n/100000000).toFixed(2)+'亿':n>=10000?(n/10000).toFixed(2)+'万':money(n);
const rankBadge=i=>`<span class="receipt-rank rank-${i+1}">${i+1}</span>`;
function marketRanking(channel,title){const rows=receiptMarketRows(channel),max=Math.max(110,...rows.map(x=>x.rate));return `<div class="card receipt-table-card"><h3>${title}</h3><div class="receipt-table-scroll" tabindex="0" role="region" aria-label="${title}"><table class="market-table"><thead><tr><th scope="col">排序 / 市场</th><th scope="col">实收达成率</th><th scope="col">实收 / 元</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="linked-row" data-go="market-${r.mi}" aria-label="${r.name}，点击查看门店明细"><td>${rankBadge(i)}<span>${r.name}<em class="cell-arrow">›</em></span></td><td class="${r.rate<100?'red':'green'}">${r.rate.toFixed(1)}%</td><td title="¥ ${money(r.actual)}">${receiptAmount(r.actual)}</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">合计</th><td>${(rows.reduce((n,r)=>n+r.actual,0)/rows.reduce((n,r)=>n+r.target,0)*100).toFixed(1)}%</td><td>${receiptAmount(rows.reduce((n,r)=>n+r.actual,0))}</td></tr></tfoot></table></div><p class="receipt-table-note"><i class="target-line-key"></i>点击市场行可下钻门店 · 按达成率由高到低 · 演示</p></div>`}function channelSplit(){const total=current(metrics.receipt),target=current(metrics.target);const rows=[['dining','堂食',.6],['delivery','外卖',.4]].map(([ch,name,w])=>{const v=channelRevenue(ch),t=target*w;return `<tr class="linked-row" data-go="receipt-${ch}" aria-label="${name}实收，点击查看分客群/菜品明细"><td>${name}<em class="cell-arrow">›</em></td><td title="¥ ${money(v)}">¥ ${receiptAmount(v)}</td><td>${(v/total*100).toFixed(1)}%</td><td title="¥ ${money(t)}">¥ ${receiptAmount(t)}</td><td><b class="${v<t?'red':'green'}">${(v/t*100).toFixed(1)}%</b></td></tr>`}).join('');return `<table class="market-table channel-split"><thead><tr><th scope="col">渠道</th><th scope="col">实收 / 元</th><th scope="col">占比</th><th scope="col">目标 / 元</th><th scope="col">达成率</th></tr></thead><tbody>${rows}</tbody></table><p class="receipt-table-note"><i class="target-line-key"></i>点击渠道行可下钻分客群 / 菜品 · 演示</p>`}
function paymentList(){const total=current(metrics.receipt);const pp=(d,cur)=>{const v=Math.round((cur-d)*1000)/10;return v===0?'<span class="pp0">0.0pp</span>':`<b class="${v<0?'red':'green'}">${v>0?'+':''}${v.toFixed(1)}pp</b>`};const rows=payments.map(([id,name,s,sm,sy])=>({name,share:s,mom:sm,yoy:sy,amount:total*s})).filter(r=>r.share>0).sort((a,b)=>b.amount-a.amount);return `<div class="card receipt-table-card"><h3>实收分布</h3><div class="receipt-table-scroll" tabindex="0" role="region" aria-label="实收分布"><table class="market-table payment-table"><thead><tr><th scope="col">支付类型</th><th scope="col">金额 / 元</th><th scope="col">占比</th><th scope="col">环比</th><th scope="col">同比</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.name}</td><td title="¥ ${money(r.amount)}">¥ ${receiptAmount(r.amount)}</td><td>${(r.share*100).toFixed(1)}%</td><td>${pp(r.mom,r.share)}</td><td>${pp(r.yoy,r.share)}</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">合计</th><td title="¥ ${money(total)}">¥ ${receiptAmount(total)}</td><td>100.0%</td><td><span class="pp0">0.0pp</span></td><td><span class="pp0">0.0pp</span></td></tr></tfoot></table></div></div>`}
const marketStoreCounts=[53,89,40,58,115,22,35,30];
function marketStores(i){const mr=receiptMarketRows('total').find(x=>x.mi===i),n=marketStoreCounts[i],rnd=k=>Math.sin(i*97.3+k*31.7)*.5+.5;const ws=Array.from({length:n},(_,k)=>.4+rnd(k)*1.8),wsum=ws.reduce((a,b)=>a+b,0);const targets=ws.map(w=>mr.target*w/wsum);const rates=ws.map((w,k)=>Math.max(55,Math.min(150,mr.rate+(rnd(k*3+7)-.5)*60)));const raws=rates.map((r,k)=>targets[k]*r/100);const factor=mr.actual/raws.reduce((a,b)=>a+b,0);const cities=['海滨','中心','大学城','高新','机场','老城','滨江','梧桐','龙湖','梅陇','春熙','望江','学府','东湖','南屏','北苑'];const types=['旗舰','标准','社区','快取'];const seen={};return ws.map((w,k)=>{let name=cities[(i*5+k*3)%cities.length]+types[(i*5+k*3)%types.length]+'店';seen[name]=(seen[name]||0)+1;if(seen[name]>1)name=name.slice(0,-1)+'·'+seen[name]+'店';const tp=types[(i*5+k*3)%types.length],band=tp==='旗舰'?[88,108]:tp==='标准'?[74,94]:tp==='社区'?[63,79]:[43,59],a=raws[k]*factor,g=Math.max(4,Math.round(a/(band[0]+rnd(k*7+11)*(band[1]-band[0]))));return{name,target:targets[k],actual:a,rate:a/targets[k]*100,guests:g,price:a/g}}).sort((a,b)=>b.rate-a.rate)}
function marketDetail(i){const name=receiptMarkets[i]?receiptMarkets[i][0]:receiptMarkets[0][0];if(!receiptMarkets[i])i=0;const r=receiptMarketRows('total').find(x=>x.mi===i),stores=marketStores(i);return `${filter()}${section(name+' · 门店实收')}<div class="card card-pad market-summary"><div class="metric-label">实收达成率</div><div class="detail-value ${r.rate<100?'red':'green'}">${r.rate.toFixed(1)}%</div><div class="market-summary-bar"><div><em>实收 / 元</em><b>¥ ${money(r.actual)}</b></div><div><em>目标 / 元</em><b>¥ ${money(r.target)}</b></div><div><em>门店数</em><b>${marketStoreCounts[i]}<small> 家</small></b></div></div></div>${section('门店排名')}<div class="card"><div class="receipt-table-scroll" tabindex="0" role="region" aria-label="门店实收排名"><table class="market-table"><thead><tr><th scope="col">排序 / 门店</th><th scope="col">实收达成率</th><th scope="col">实收 / 元</th><th scope="col">客流量 / 人次</th><th scope="col">客单价 / 元</th></tr></thead><tbody>${stores.map((s,k)=>`<tr><td>${rankBadge(k)}<span>${s.name}</span></td><td class="${s.rate<100?'red':'green'}">${s.rate.toFixed(1)}%</td><td title="¥ ${money(s.actual)}">${receiptAmount(s.actual)}</td><td>${s.guests.toLocaleString('zh-CN')}</td><td>${s.price.toFixed(1)}</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">合计</th><td>${r.rate.toFixed(1)}%</td><td>${receiptAmount(r.actual)}</td><td>${stores.reduce((n,s)=>n+s.guests,0).toLocaleString('zh-CN')}</td><td>${(r.actual/stores.reduce((n,s)=>n+s.guests,0)).toFixed(1)}</td></tr></tfoot></table></div></div><p class="receipt-table-note">门店为模拟拆分 · 按达成率由高到低 · 演示</p><button class="back-home" data-go="receipt">返回门店实收</button>${footer()}`}
