function channelAttributionData(channel){const dining=channel==='dining',yoy=state.comparison==='yoy',data=dining?{oldQuantity:(yoy?30416:33133)*days(),oldPrice:100,newPrice:channelRevenue(channel)/channelRows(channel).reduce((n,r)=>n+r.quantity,0),quantity:channelRows(channel).reduce((n,r)=>n+r.quantity,0)}:{oldQuantity:(yoy?39760:43074)*days(),oldPrice:50,newPrice:49.7,quantity:40000*days()};return {...data,before:data.oldQuantity*data.oldPrice,now:channelRevenue(channel),rows:[[dining?'堂食销量变化':'外卖订单量变化',(data.quantity-data.oldQuantity)*data.oldPrice],[dining?'堂食客单价变化':'外卖单均实收变化',data.quantity*(data.newPrice-data.oldPrice)]]}}
function channelAttribution(channel){const dining=channel==='dining',a=channelAttributionData(channel),max=Math.max(1,...a.rows.map(x=>Math.abs(x[1]))),delta=a.now-a.before;return `<div class="card receipt-analysis"><h3>${dining?'堂食':'外卖'}实收归因分析</h3><div class="tabs"><button data-compare="mom" class="${state.comparison==='mom'?'active':''}">环比</button><button data-compare="yoy" class="${state.comparison==='yoy'?'active':''}">同店同比</button></div><p class="receipt-table-note">对比期：${rangeText(compareRange())}</p><div class="receipt-bridge"><div><small>对比期实收</small><b>¥ ${receiptAmount(a.before)}</b></div><span>→</span><div><small>本期实收</small><b>¥ ${receiptAmount(a.now)}</b></div><div><small>变化金额</small><b class="${delta<0?'red':'green'}">${delta>0?'+':''}${receiptAmount(delta)}</b></div></div>${a.rows.map(([n,v])=>`<div class="receipt-driver"><div><span>${n}</span><b class="${v<0?'red':'green'}">${v>0?'+':''}${money(v)} 元</b></div><div class="contribution-bar"><span style="width:${Math.abs(v)/max*100}%;background:${v<0?'#f16a77':'#51bc9b'}"></span></div></div>`).join('')}<div class="receipt-driver-total"><span>贡献合计</span><b>${delta>0?'+':''}${money(delta)} 元</b></div><div class="receipt-factor-grid"><span>驱动因子</span><span>对比期</span><span>本期</span><span>${dining?'堂食销量 / 人次':'外卖订单 / 单'}</span><b>${money(a.oldQuantity)}</b><b>${money(a.quantity)}</b><span>${dining?'客单价 / 元':'单均实收 / 元'}</span><b>${a.oldPrice.toFixed(2)}</b><b>${a.newPrice.toFixed(2)}</b></div><p class="receipt-table-note">实收＝${dining?'销量×客单价':'订单量×单均实收'}。先替换数量，再替换价格，贡献合计与实收差额一致。演示数学拆解，不代表已验证的经营原因。</p></div>`}
function receiptChannel(channel){const dining=channel==='dining',value=channelRevenue(channel),target=current(metrics.target)*(dining?.6:.4);return `${section(dining?'堂食实收':'外卖实收')}<div class="card receipt-channel-summary"><div><span>${dining?'堂食':'外卖'}实收</span><b>¥ ${receiptAmount(value)}</b></div><div><span>实收占比</span><b>${(value/current(metrics.receipt)*100).toFixed(1)}%</b></div><div><span>目标达成率</span><b class="${value<target?'red':'green'}">${(value/target*100).toFixed(1)}%</b></div></div>${channelTable(channel)}${marketRanking(channel,dining?'堂食实收 · 分市场':'外卖实收 · 分市场')}${channelAttribution(channel)}`}
