if(m.id==='profit'){return {note:'实收增减减去各项成本费用增减，合计即预算利润变化。各项均按同一周期和同一门店集合比较。',rows:[['实收变化',current(metrics.receipt)-previous(metrics.receipt)],...costs.map(([id,n])=>[n+'变化',previous(metrics[id])-current(metrics[id])])]}}
