function detailQuadrant(id){const m=metrics[id],v=current(m);return `${filter()}<div class="card card-pad"><div class="metric-label">${m.name}</div><div class="detail-value">${fmt(v,m)}<small>${unit(m)}</small></div>${changes(m)}<h3>指标趋势</h3>${chart(m)}<div class="definition">${m.formula}</div></div>${storeList(id)}<button class="back-home" data-go="home">返回集团看板</button>${footer()}`}
const openingCriteria=[['爬坡达标','开业 6 个月内月营收达到区域成熟门店的 85%'],['单店盈亏平衡','开业 3 个月内实现月度经营现金流转正'],['投资回收期','预计投资回收期 ≤ 24 个月'],['坪效达标','达到区域同品牌坪效基准的 90%'],['品质合格','首次 QSC 稽核 ≥ 80 分且无重大食安扣分']];
const openingStores=[['科技园店','华南市场','直营',[1,1,1,1,1]],['会展中心店','华东市场','直营',[1,1,1,1,1]],['滨江天街店','华东市场','直营',[1,1,1,1,1]],['万象城店','华南市场','直营',[1,1,1,1,1]],['高铁新城店','华中市场','直营',[1,1,1,1,1]],['大学城二店','华中市场','直营',[1,1,1,1,1]],['星光天地店','华北市场','直营',[1,1,1,1,1]],['融创茂店','西南市场','直营',[1,1,1,1,1]],['桃源居店','华南市场','直营',[1,1,1,1,1]],['空港新城店','华北市场','加盟',[1,1,1,1,1]],['生态公园店','西南市场','加盟',[0,1,1,0,1]],['老城根店','华中市场','加盟',[1,0,1,1,1]]];
function openingAnalysis(){const rows=[['本期新开店数','直营 9 + 加盟 3',12],['达到成功标准','五项标准全部达标',10],['未达标（观察期）','选址客流不及预期，进入帮扶名单',2]];return `${section('新开店分析','点击门店数查看评估明细')}<div class="opening-cards">${rows.map(([t,s,n])=>`<button class="opening-card" data-go="opening-stores"><i aria-hidden="true">▦</i><div><b>${t}</b><span>${s}</span></div><strong>${n}<small>家</small></strong></button>`).join('')}</div>`}
function openingCriteriaList(){return `${section('新开店成功标准')}<div class="card card-pad"><ol class="opening-criteria">${openingCriteria.map(([t,d])=>`<li><b>${t}</b><span>${d}</span></li>`).join('')}</ol></div>`}
function openingDetail(id){const m=metrics[id],v=current(m);return `${filter()}<div class="card card-pad"><div class="metric-label">${m.name}</div><div class="detail-value">${fmt(v,m)}<small>${unit(m)}</small></div>${changes(m)}<h3>指标趋势</h3>${chart(m)}<div class="definition">${m.formula}</div></div>${openingAnalysis()}${openingCriteriaList()}<button class="back-home" data-go="home">返回集团看板</button>${footer()}`}
function openingStoreList(){const mark=ok=>ok?'<b class="green">✓</b>':'<b class="red">✗</b>';const rows=openingStores.map(([name,market,type,flags])=>{const okAll=flags.every(Boolean);return `<tr><td><b>${name}</b><em class="cell-sub">${market} · ${type}</em></td>${flags.map(f=>`<td>${mark(f)}</td>`).join('')}<td><b class="${okAll?'green':'orange'}">${okAll?'达标':'观察期'}</b></td></tr>`}).join('');return `${filter()}<div class="card card-pad"><div class="metric-label">新开店 · 五项标准评估</div><div class="metric-hint">本期新开店 12 家：直营 9 + 加盟 3；达标 10 家，观察期 2 家。</div></div>${section('门店列表','五项标准评估情况 · 演示')}<div class="card receipt-table-card"><div class="receipt-table-scroll" tabindex="0" role="region" aria-label="新开店五项标准评估"><table class="market-table opening-table"><thead><tr><th scope="col">门店 / 市场 / 类型</th>${openingCriteria.map(([t],i)=>`<th scope="col">${['爬坡','盈亏平衡','回收期','坪效','品质'][i]}</th>`).join('')}<th scope="col">结论</th></tr></thead><tbody>${rows}</tbody></table></div><p class="receipt-table-note">✓ 达标 · ✗ 未达标 · 观察期门店进入帮扶名单 · 演示数据</p></div><button class="back-home" data-go="opening">返回开店成功 ›</button>${footer()}`}
function detail(id){if(id==='receipt')return receiptOverview();if(quadrants.some(q=>q[0]===id))return detailQuadrant(id);if(id==='opening')return openingDetail(id);const m=metrics[id],v=current(m),b=previous(m),delta=v-b,a=attribution(m);const deltaUnit=m.kind==='rate'?'个百分点':m.unit;return `${filter()}${id==='receipt'?receiptOverview():id==='fulltime'?'':`<div class="card card-pad">${m.base||m.shareMetric?`<div class="tabs"><button data-go="${m.base||m.id}" class="${m.base?'':'active'}">${m.unit==='单'||(m.base&&metrics[m.base].unit==='单')?'订单量':m.unit==='人次'||(m.base&&metrics[m.base].unit==='人次')?'流量':'金额'}</button><button data-go="${m.base?m.id:m.shareMetric}" class="${m.base?'active':''}">占比</button></div>`:''}<div class="metric-label">${m.name}</div><div class="detail-value">${fmt(v,m)}<small>${unit(m)}</small></div>${changes(m)}${m.share!==undefined?`<div class="metric-hint">${costs.some(x=>x[0]===m.id)?'占实收':payments.some(x=>x[0]===m.id)?'支付占比':'流量占比'} ${(m.share*100).toFixed(1)}%</div>`:''}${id==='profit'?`<div id="profit-trend">`:''}<h3>指标趋势</h3>${chart(m)}${id==='profit'?'</div>':''}<div class="definition">${m.formula}</div></div>`}${id==='stores'?`${section('在营门店类型')}<div class="card"><div class="ownership">${owners.map(([id,n,v])=>`<button data-go="${id}"><span>${n} ›</span><b>${v}<small>家</small></b></button>`).join('')}</div></div>`:''}${overviewDetails(id)}${id==='profit'?`${profitBreakdown()}`:id==='groupProfit'?`<div class="card metric-grid">${metricCard('groupProfitTarget')}${metricCard('groupCost')}</div>`:''}${id==='fulltime'?`<div id="fulltime-trend">${section('指标趋势')}<div class="card card-pad">${chart(m)}</div></div>`:''}${section('归因分析')}<div class="card card-pad"><div class="tabs"><button data-compare="mom" class="${state.comparison==='mom'?'active':''}">环比</button><button data-compare="yoy" class="${state.comparison==='yoy'?'active':''}">${m.sameStore?'同店同比':'同比'}</button></div><div class="explain">对比期：${rangeText(compareRange())}</div><div class="bridge-summary"><div><span>对比期</span><b>${fmt(b,m,false)}</b></div><em>→</em><div><span>本期</span><b>${fmt(v,m,false)}</b></div><div><span>净变化 / ${deltaUnit}</span><b class="${delta<0?'red':'green'}">${delta>0?'+':''}${fmt(delta,m,false)}</b></div></div><div class="explain">${a.note} 显示值四舍五入，可能存在尾差。</div></div><div class="card">${a.rows.map(([name,n])=>`<div class="contribution-row"><div class="row"><span>${name}</span><b class="${n<0?'red':'green'}">${n>0?'+':''}${fmt(n,m,false)}<small>${a.unit||deltaUnit}</small></b></div><div class="contribution-bar"><span style="width:${Math.min(100,Math.abs(n)/(Math.max(...a.rows.map(x=>Math.abs(x[1])))||1)*100)}%;background:${n<0?'#f16a77':'#51bc9b'}"></span></div></div>`).join('')}<div class="contribution-total">贡献合计 <b>${a.unit?`${a.rows.reduce((n,x)=>n+x[1],0)>0?'+':''}${fmt(a.rows.reduce((n,x)=>n+x[1],0),m,false)} ${a.unit}（${delta>0?'+':''}${fmt(delta,m,false)} ${deltaUnit}）`:`${delta>0?'+':''}${fmt(a.rows.reduce((n,x)=>n+x[1],0),m,false)} ${deltaUnit}`}</b></div></div>${a.equations?`<div class="card table-wrap"><table><thead><tr><th>实收驱动因子</th><th>对比期</th><th>本期</th></tr></thead><tbody>${a.equations.map(([n,b,v,u])=>`<tr><td>${n} / ${u}</td><td>${money(b)}</td><td>${money(v)}</td></tr>`).join('')}</tbody></table><div class="card-pad explain">堂食：${money(29820*days())}人次 × 100元 = ${money(flow(2982000))}元<br>外卖：${money(40000*days())}单 × 49.7元 = ${money(flow(1988000))}元</div></div>`:''}<button class="back-home" data-go="home">返回集团看板</button>${footer()}`}
function visitDetail(index){const v=visits[index]||visits[0];return `${filter()}<div class="card card-pad"><div class="row"><h2 class="visit-heading">${v.store}</h2><span class="pill ${v.color}">${v.priority}</span></div><p class="minor muted">${v.market} · ${v.owner}</p><p class="minor">${v.issue}</p></div>${section('巡店重点')}<div class="card card-pad"><p class="minor">${v.action}</p><ol class="visit-checklist"><li>核对异常指标的原始凭证、班次和统计口径。</li><li>现场确认原因，记录证据与负责岗位。</li><li>约定整改时限，复查同口径指标及执行结果。</li></ol></div>${section('量化依据')}<div class="card">${metricCard(v.metric)}${metricCard('profit')}${metricCard('food')}</div><div class="notice">该门店案例为模拟。下方指标穿透为集团口径，用于展示趋势与归因流程。</div><button class="back-home" data-go="${v.metric}">查看${metrics[v.metric].name}趋势与归因 ›</button>${footer()}`}
function dialogs(){const month=state.day==='month',week=state.day==='week',type=month?'month':'date',r=dateRange(),value=v=>month?v.slice(0,7):v,min=month?'2020-01':'2020-01-01',max=month?'2035-12':week?shiftDate(todayDate(),-1):'2035-12-31';return `<dialog id="date-dialog" aria-labelledby="date-dialog-title"><form id="date-form"><h3 id="date-dialog-title">${month?'选择月份期间':week?'选择周期间':'选择日期区间'}</h3><div class="date-range-fields"><label for="date-input">${month?'开始月份':'开始日期'}</label><input id="date-input" type="${type}" value="${value(week?r.start:state.date)}" min="${min}" max="${max}" required><label for="date-end">${month?'结束月份':'结束日期'}</label><input id="date-end" type="${type}" value="${value(r.end)}" min="${min}" max="${max}" required></div><p class="date-range-help">${month?'包含开始与结束月份，按完整自然月汇总。':week?'起止日期按所在周统计：历史周为周一至周日，当前周为周一至昨天（北京时间）。':'包含开始与结束日期；选择同一天可筛选单日。'}</p><p id="date-error" role="alert" hidden></p><div class="date-actions"><button type="button" id="date-cancel">取消</button><button type="submit">确定</button></div></form></dialog>`}
function applyDateRange(e){e.preventDefault();const month=state.day==='month',week=state.day==='week',start=document.getElementById('date-input').value,end=document.getElementById('date-end').value,first=month?start+'-01':start,last=month?end+'-01':end,error=document.getElementById('date-error');if(!validDate(first)||!validDate(last)||first>last){error.textContent=month?'结束月份不能早于开始月份。':'结束日期不能早于开始日期。';error.hidden=false;return}if(week&&last>=todayDate()){error.textContent='周统计仅包含昨天及以前的日期。';error.hidden=false;return}state.date=week?weekStart(first):first;state.endDate=week?(weekStart(first)===weekStart(last)?null:weekStart(last)):first===last?null:last;state.point=null;persist();render();document.getElementById('date-open').focus()}
function render(){if(!['day','week','month'].includes(state.day))state.day='day';if(!validDate(state.date))state.date='2026-09-18';if(state.day==='week'){const latest=shiftDate(todayDate(),-1);if(state.date>latest){state.date=latest;state.endDate=null}if(state.endDate&&state.endDate>latest)state.endDate=latest}const id=route(),isMetric=!!metrics[id],isVisit=id.startsWith('visit-'),isMarket=id.startsWith('market-'),isChannel=id==='receipt-dining'||id==='receipt-delivery'||id==='opening-stores',isHome=!isMetric&&!isVisit&&!isMarket&&!isChannel;const title=isHome?'老板看板':id==='receipt'?'门店实收':id==='receipt-dining'?'堂食实收':id==='receipt-delivery'?'外卖实收':id==='opening-stores'?'新开店门店列表':id==='profit'?'门店利润':isMetric?metrics[id].name:isMarket?(receiptMarkets[Number(id.slice(7))]||receiptMarkets[0])[0]+' · 门店明细':'巡店建议';document.title=title+' · 集团演示';document.getElementById('app').classList.toggle('home-view',isHome);document.getElementById('app').innerHTML=(isHome?homeHeader(title):`<header><button id="back" aria-label="返回上一页">‹</button><h1>${title}</h1><span class="demo">DEMO</span></header>`)+(isHome?home():isMetric?detail(id):isChannel?id==='opening-stores'?openingStoreList():channelDetail(id.slice(8)):isMarket?marketDetail(Number(id.slice(7))):visitDetail(Number(id.slice(6))))+dialogs();document.querySelectorAll('[data-go]').forEach(e=>e.onclick=()=>go(e.dataset.go));document.querySelectorAll('[data-scroll]').forEach(e=>e.onclick=()=>document.getElementById(e.dataset.scroll)?.scrollIntoView({block:'start'}));document.querySelectorAll('[data-date-type]').forEach(e=>e.onclick=()=>{state.day=e.dataset.dateType;state.endDate=null;state.point=null;persist();render();document.getElementById('date-control').open=true;document.querySelector('[data-date-type="'+state.day+'"]').focus()});document.querySelectorAll('[data-compare]').forEach(e=>e.onclick=()=>{state.comparison=e.dataset.compare;persist();render()});document.querySelectorAll('[data-point]').forEach(e=>e.onclick=()=>{state.point=Number(e.dataset.point);render()});document.querySelectorAll('[data-date-value]').forEach(e=>e.onclick=()=>{state.date=e.dataset.dateValue;state.endDate=null;state.point=null;persist();render();document.getElementById('date-open').focus()});document.getElementById('date-other').onclick=()=>{document.getElementById('date-control').open=false;document.getElementById('date-dialog').showModal()};document.getElementById('date-cancel').onclick=()=>document.getElementById('date-dialog').close();document.getElementById('date-form').onsubmit=applyDateRange;const back=document.getElementById('back');if(back)back.onclick=()=>history.state?.depth>0?history.back():go('home')}
document.addEventListener('click',e=>{const picker=document.getElementById('date-control');if(picker&&!e.target.closest('.date-control'))picker.open=false});document.addEventListener('keydown',e=>{const picker=document.getElementById('date-control');if(e.key==='Escape'&&picker?.open){picker.open=false;document.getElementById('date-open').focus()}});
history.scrollRestoration='manual';if(history.state?.filters)Object.assign(state,{endDate:null},history.state.filters);window.addEventListener('popstate',()=>{if(history.state?.filters)Object.assign(state,{endDate:null},history.state.filters);render();window.scrollTo(0,history.state?.scroll||0)});render();persist();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_dashboard_filters',description:'切换集团看板的日期类型与日期，所有指标同步展示。',inputSchema:{type:'object',properties:{day:{type:'string',enum:['day','week','month']},date:{type:'string'}},required:['day','date'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!['day','week','month'].includes(input.day)||!validDate(input.date))throw Error('日期无效');Object.assign(state,{day:input.day,date:input.date,endDate:null,point:null});persist();render();return {range:dateRange(),simulated:true}}})).catch(()=>{});}catch{}}
